mapper.select:



        EXISTS (SELECT 1 FROM sys_role_menu rm
            JOIN sys_role sr ON rm.role_id = sr.role_id
            JOIN sys_user_role sur ON sr.role_id = sur.role_id
        WHERE
            sur.user_id = #{userId}
            AND sr.status = '1'
            AND sr.del_flag = '0'
            AND sm.menu_id = rm.menu_id
        )

     and sm.menu_name like concat(concat('%', #{menuName}), '%')
     and sm.component_name like concat(concat('%', #{componentName}), '%')
     and sm.visible = #{visible}
     and sm.status = #{status}
     and sm.menu_type = #{menuType}

        and sm.menu_type in

            #{item}


     and sm.parent_id = #{parentId}

order by parent_id, order_num
